CREATE TABLE maintenance_jobs(id BINARY(16) PRIMARY KEY,job_number VARCHAR(40) NOT NULL UNIQUE,tenant_id BINARY(16) NOT NULL,title VARCHAR(180) NOT NULL,description TEXT,type VARCHAR(40) NOT NULL,station_id BINARY(16),charger_id BINARY(16),technician_id BINARY(16),technician_name VARCHAR(120),scheduled_at TIMESTAMP(6) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,INDEX idx_maintenance_tenant(tenant_id,scheduled_at));
CREATE TABLE amc_contracts(id BINARY(16) PRIMARY KEY,contract_number VARCHAR(40) NOT NULL UNIQUE,tenant_id BINARY(16) NOT NULL,partner_id BINARY(16) NOT NULL,station_id BINARY(16) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,amount DECIMAL(12,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMP(6) NOT NULL,INDEX idx_amc_tenant(tenant_id,created_at));
